package com.example.starter.rosbridge.ros;

/**
 * ROS 2 QoS 策略的最小描述，参与共享上游订阅的去重键。
 *
 * @param reliability 可靠性策略：RELIABLE / BEST_EFFORT
 * @param durability  持久性策略：VOLATILE / TRANSIENT_LOCAL
 * @param depth       历史深度，正整数
 */
public record Qos(String reliability, String durability, int depth) {

    public static final String RELIABLE = "RELIABLE";
    public static final String BEST_EFFORT = "BEST_EFFORT";
    public static final String VOLATILE = "VOLATILE";
    public static final String TRANSIENT_LOCAL = "TRANSIENT_LOCAL";

    public Qos {
        reliability = reliability == null || reliability.isBlank() ? RELIABLE : reliability.trim().toUpperCase();
        durability = durability == null || durability.isBlank() ? VOLATILE : durability.trim().toUpperCase();
        if (depth <= 0) {
            depth = 10;
        }
    }

    public static Qos defaults() {
        return new Qos(RELIABLE, VOLATILE, 10);
    }

    /** 生成规范化的 QoS 去重键。 */
    public String key() {
        return reliability + "|" + durability + "|" + depth;
    }
}

package com.example.starter.rosbridge.ros;

import com.fasterxml.jackson.databind.JsonNode;

/**
 * Service 调用的适配器回调结果。
 *
 * @param ok    适配器是否成功返回
 * @param value 成功时的返回内容（JSON）
 * @param error 失败时的错误文本
 */
public record ServiceOutcome(boolean ok, JsonNode value, String error) {

    public static ServiceOutcome success(JsonNode value) {
        return new ServiceOutcome(true, value, null);
    }

    public static ServiceOutcome failure(String error) {
        return new ServiceOutcome(false, null, error);
    }
}

package com.example.starter.rosbridge.ros;

import com.fasterxml.jackson.databind.JsonNode;

/**
 * Action goal 的最终结果。
 *
 * @param status SUCCEEDED=成功，ABORTED=异常终止
 * @param result 结果内容（JSON）
 */
public record GoalOutcome(String status, JsonNode result) {

    public static final String SUCCEEDED = "SUCCEEDED";
    public static final String ABORTED = "ABORTED";

    public static GoalOutcome succeeded(JsonNode result) {
        return new GoalOutcome(SUCCEEDED, result);
    }

    public static GoalOutcome aborted(String error) {
        return new GoalOutcome(ABORTED, null);
    }
}

package com.example.starter.rosbridge.ros;

/**
 * 适配器侧 Action goal 句柄，用于向适配器发起取消。
 */
public interface GoalHandle {

    /** 请求适配器取消 goal；幂等，重复调用无副作用。 */
    void cancel();
}

package com.example.starter.rosbridge.ros;

import com.fasterxml.jackson.databind.JsonNode;
import java.util.function.Consumer;

/**
 * 可注入的 ROS 2 适配层。网关不依赖真实 ROS，生产环境可替换为 rcljava / 进程桥接实现，
 * 测试与本地启动使用合成实现。
 */
public interface RosAdapter {

    /**
     * 建立一个上游 Topic 订阅。
     *
     * @param topic    Topic 名称
     * @param type     消息类型（如 std_msgs/String）
     * @param qos      QoS 策略
     * @param messageSink 上游消息回调，参数为消息体 JSON
     * @return 用于释放上游订阅的句柄
     */
    AutoCloseable subscribe(String topic, String type, Qos qos, Consumer<JsonNode> messageSink);

    /**
     * 发起一次 Service 调用，完成时回调（可能成功或失败）。适配器不感知超时，
     * 超时由网关判定，迟到回调必须被忽略。
     */
    void callService(String service, String type, JsonNode args, Consumer<ServiceOutcome> callback);

    /**
     * 提交一个 Action goal。
     *
     * @param feedbackSink feedback 回调（可多次）
     * @param resultSink   最终结果回调（仅一次）
     * @return goal 句柄，可用于取消
     */
    GoalHandle sendGoal(String action, String type, JsonNode goal,
                        Consumer<JsonNode> feedbackSink, Consumer<GoalOutcome> resultSink);
}

package com.example.starter.rosbridge.ros;

import org.springframework.stereotype.Component;

/**
 * 可控时钟，业务逻辑统一取这里的时间，测试中可拨快以验证宽限期与超时。
 */
@Component
public class GatewayClock {

    /** 0 表示跟随系统时钟；大于 0 时为测试设定的固定/虚拟时间（UTC 纪元毫秒）。 */
    private volatile long fixedMillis = 0L;

    public long nowMillis() {
        return fixedMillis > 0 ? fixedMillis : System.currentTimeMillis();
    }

    /** 测试用：设定虚拟当前时间。 */
    public void setFixedMillis(long millis) {
        this.fixedMillis = millis;
    }

    /** 测试用：在虚拟时间轴上推进。 */
    public void advance(long deltaMillis) {
        if (fixedMillis == 0L) {
            fixedMillis = System.currentTimeMillis();
        }
        fixedMillis += deltaMillis;
    }

    /** 测试用：恢复系统时钟。 */
    public void reset() {
        this.fixedMillis = 0L;
    }
}

