package com.example.starter.rosbridge.gateway;

/**
 * 客户端出站队列中的条目。文本帧为普通响应；Topic 帧带共享订阅与游标，
 * 用于慢消费者丢弃与缺口合并；缺口帧可变范围，用于合并相邻丢弃。
 */
public sealed interface OutboundEntry {

    String render();

    /** 普通文本帧。 */
    record Text(String frame) implements OutboundEntry {
        @Override
        public String render() {
            return frame;
        }
    }

    /** 共享订阅消息帧。 */
    record Topic(long sharedId, long cursor, String frame) implements OutboundEntry {
        @Override
        public String render() {
            return frame;
        }
    }

    /** 丢失游标缺口帧；相邻丢弃会就地扩展范围。 */
    final class Gap implements OutboundEntry {
        private final String frameRenderer;
        private long fromCursor;
        private long toCursor;

        public Gap(long cursor, String frameRenderer) {
            this.fromCursor = cursor;
            this.toCursor = cursor;
            this.frameRenderer = frameRenderer;
        }

        public long fromCursor() {
            return fromCursor;
        }

        public long toCursor() {
            return toCursor;
        }

        /** 若 cursor 与当前缺口末端相邻则扩展并返回 true。 */
        public boolean extendIfAdjacent(long cursor) {
            if (cursor == toCursor + 1) {
                toCursor = cursor;
                return true;
            }
            return false;
        }

        @Override
        public String render() {
            // frameRenderer 接收 [from,to] 后生成最终帧
            return renderGap(frameRenderer, fromCursor, toCursor);
        }

        private static String renderGap(String renderer, long from, long to) {
            // 渲染器格式为 "RESUME_GAP\u0000<topic>\u0000<type>\u0000<qos>"，由会话层组装
            String[] parts = renderer.split("\u0000", 4);
            return com.example.starter.rosbridge.protocol.Protocol.resumeGap(
                    parts[1], parts[2], parts[3], from, to);
        }
    }
}

