package com.example.starter.rosbridge.testsupport;

import com.example.starter.rosbridge.gateway.ClientTransport;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * 测试用传输：记录全部已发送帧，可控开关状态，不依赖真实容器。
 */
public class RecordingTransport implements ClientTransport {

    private final String clientId;
    private final List<String> sent = new CopyOnWriteArrayList<>();
    private volatile boolean open = true;
    private volatile int failAfter = Integer.MAX_VALUE;

    public RecordingTransport(String clientId) {
        this.clientId = clientId;
    }

    @Override
    public String clientId() {
        return clientId;
    }

    @Override
    public boolean isOpen() {
        return open;
    }

    @Override
    public boolean sendText(String text) {
        if (!open) {
            return false;
        }
        if (sent.size() >= failAfter) {
            return false;
        }
        sent.add(text);
        return true;
    }

    @Override
    public void close() {
        open = false;
    }

    public List<String> sent() {
        return new ArrayList<>(sent);
    }

    public void setFailAfter(int n) {
        this.failAfter = n;
    }

    public void reopen() {
        open = true;
    }

    public void clear() {
        sent.clear();
    }
}

package com.example.starter.rosbridge.testsupport;

import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;

/**
 * 构造隔离的 H2 内存库（MySQL 兼容模式）并执行 schema.sql 的测试工具。
 */
public final class TestDatasources {

    private TestDatasources() {
    }

    public static DataSource newH2(String dbName) {
        DriverManagerDataSource ds = new DriverManagerDataSource();
        ds.setDriverClassName("org.h2.Driver");
        ds.setUrl("jdbc:h2:mem:" + dbName
                + ";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");
        ds.setUsername("sa");
        ds.setPassword("");
        new org.springframework.jdbc.datasource.init.ResourceDatabasePopulator(
                new org.springframework.core.io.ClassPathResource("schema.sql"))
                .execute(ds);
        return ds;
    }

    public static JdbcTemplate jdbc(DataSource ds) {
        return new JdbcTemplate(ds);
    }
}

