package com.example.starter.rosbridge.gateway;

import java.util.ArrayList;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * 单个客户端连接的内存态：有界发送队列、令牌桶限速、慢消费者丢弃策略。
 *
 * <p>队列满时：仅丢弃队列中最旧的一条 Topic 消息，并在其位置插入（或与已有的相邻缺口
 * 合并）一个 {@link OutboundEntry.Gap}，最终渲染为 RESUME_GAP 帧。丢弃只影响本客户端，
 * 不触碰共享留存与其他客户端。控制帧（service_response/action_result 等）不被丢弃。</p>
 *
 * <p>线程模型：所有入队/出队均在会话锁内完成；实际网络发送在锁外执行，
 * 每次最多取出当前令牌允许的一批，避免长持锁。</p>
 */
public class ClientSession {

    private static final Logger log = LoggerFactory.getLogger(ClientSession.class);

    private final String clientId;
    private final ClientTransport transport;
    private final int ratePerSec;
    private final int queueCap;

    private final List<OutboundEntry> queue = new ArrayList<>();

    // 令牌桶：容量=每秒配额，按经过时间连续补充
    private double tokens;
    private long lastRefillNanos = System.nanoTime();

    public ClientSession(String clientId, ClientTransport transport,
                         int ratePerSec, int queueCap) {
        this.clientId = clientId;
        this.transport = transport;
        this.ratePerSec = ratePerSec;
        this.queueCap = queueCap;
        this.tokens = ratePerSec;
    }

    public String clientId() {
        return clientId;
    }

    public ClientTransport transport() {
        return transport;
    }

    public int ratePerSec() {
        return ratePerSec;
    }

    public int queueCap() {
        return queueCap;
    }

    public synchronized int queuedSize() {
        return queue.size();
    }

    /**
     * 入队一条 Topic 消息；队列满时按最旧未确认 Topic 丢弃策略处理。
     * 供重连续传使用的批量入队见 {@link #enqueueResumeBatch}。
     */
    public void enqueueTopic(long sharedId, long cursor, String frame,
                             String topic, String type, String qosKey) {
        enqueue(new OutboundEntry.Topic(sharedId, cursor, frame), topic, type, qosKey);
    }

    /** 控制帧入队；不会被慢消费者策略丢弃（必要时略微突破上限，数量受请求频率约束）。 */
    public synchronized void enqueueText(String frame) {
        if (!transport.isOpen()) {
            return;
        }
        if (queue.size() >= queueCap && !evictOldestTopic(null, null, null)) {
            // 队列里只有控制帧，无法按协议丢弃：放行该控制帧，限速仍然生效
            log.debug("客户端 {} 控制帧队列已满，放行控制帧（当前 {} 条）", clientId, queue.size());
        }
        queue.add(new OutboundEntry.Text(frame));
    }

    /**
     * 重连后批量补投留存消息（游标升序）。同样应用队列上限与丢弃策略；
     * 由于补投量可能大于队列，只有最近窗口内的消息能进入队列，更早的部分合并为缺口。
     */
    public void enqueueResumeBatch(List<OutboundEntry.Topic> backlog,
                                   String topic, String type, String qosKey) {
        for (OutboundEntry.Topic t : backlog) {
            enqueue(t, topic, type, qosKey);
        }
    }

    private synchronized void enqueue(OutboundEntry entry,
                                      String topic, String type, String qosKey) {
        if (!transport.isOpen()) {
            return;
        }
        if (queue.size() >= queueCap) {
            evictOldestTopic(topic, type, qosKey);
        }
        queue.add(entry);
    }

    /**
     * 丢弃队列中最旧的 Topic 消息并插入/合并缺口。
     * 返回是否成功丢弃；无 Topic 可丢时返回 false。
     */
    private boolean evictOldestTopic(String topic, String type, String qosKey) {
        int idx = -1;
        OutboundEntry.Topic dropped = null;
        for (int i = 0; i < queue.size(); i++) {
            if (queue.get(i) instanceof OutboundEntry.Topic t) {
                idx = i;
                dropped = t;
                break;
            }
        }
        if (dropped == null) {
            return false;
        }
        queue.remove(idx);
        String gapTopic = topic != null ? topic : "";
        String gapType = type != null ? type : "";
        String gapQos = qosKey != null ? qosKey : "";
